import java.util.*;class RiverCourseTest{public static void main(String[]a){int n=128;float[] h=new float[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++){double r=Math.hypot(x-64,z-65);h[z*n+x]=(float)(180-z*1.05-(r<13?35*(1-r/13):0));}var env=new EnvironmentMap(h);var routing=RiverCourse.route(h,env,n,1024,62,()->false);int cell=20*n+64,steps=0;double nearest=999;Set<Integer> seen=new HashSet<>();while(cell>=0){if(!seen.add(cell))throw new AssertionError("Routing cycle");nearest=Math.min(nearest,Math.hypot(cell%n-64,cell/n-65));cell=routing.flow().parent()[cell];steps++;}if(nearest<12||steps<50)throw new AssertionError("Route entered pit / wrong outlet: "+nearest+" steps="+steps);if(Math.abs(7*RiverCourse.width(.6,1500)-7)>1)throw new AssertionError("Middle-course width lost 7-block nominal setting");double upper=RiverCourse.maturity(350,62,.08,.1),lower=RiverCourse.maturity(66,62,.002,.95);if(upper>.2||lower<.9||RiverCourse.width(upper,100)>=RiverCourse.width(lower,10000)||RiverCourse.depth(3,upper)>=RiverCourse.depth(3,lower)||RiverCourse.bankRise(upper)<=RiverCourse.bankRise(lower)||RiverCourse.bend(upper)>=RiverCourse.bend(lower))throw new AssertionError("Course progression broken");if(routing.area()[100*n+64]<1)throw new AssertionError("Missing catchment");System.out.println("PASS: acyclic routing skirts enclosed depression (closest="+nearest+" cells), upstream/downstream width/depth/bend/valley progression");}}
